import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";

const eslintConfig = defineConfig([
  ...nextVitals,
  ...nextTs,
  // Override default ignores of eslint-config-next.
  globalIgnores([
    // Default ignores of eslint-config-next:
    ".next/**",
    "out/**",
    "build/**",
    "next-env.d.ts",
  ]),
  {
    // `src/lib/api/` is generated by Orval. The config runs with `clean: true`,
    // which wipes the whole directory before regenerating it, so any
    // hand-written file placed there is deleted on the next `pnpm orval`.
    //
    // Feature-specific hooks therefore belong in `src/features/<domain>/hooks/`.
    // The generated barrel `src/lib/api/index.ts` is the only supported entry
    // point into that tree.
    files: ["src/**/*.{ts,tsx}"],
    ignores: ["src/lib/api/**"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: ["@/lib/api/*"],
              message:
                "src/lib/api/ is generated by Orval (clean: true deletes hand-written files there). Import from '@/lib/api' or put feature hooks in src/features/<domain>/hooks/.",
            },
          ],
        },
      ],
    },
  },
  {
    // The generated tree is off-limits for hand-written code, so lint it as
    // read-only: report its problems but never fail the run on them.
    files: ["src/lib/api/**/*.{ts,tsx}"],
    rules: {
      "no-restricted-imports": "off",
    },
  },
]);

export default eslintConfig;
